from pathlib import Path

policing = Path("tests/test_policing_context_roadmap.py")
text = policing.read_text()
anchor = "    return destination\n\n\ndef _replace_inline_markdown_links_for_visibility"
assert anchor in text
text = text.replace(anchor, '    return destination\n\n\ndef _decode_markdown_destination_for_scheme(destination: str) -> str:\n    """Decode only CommonMark character references and punctuation escapes."""\n    reference = re.compile(\n        r"&(?:#[0-9]{1,7}|#[xX][0-9A-Fa-f]{1,6}|[A-Za-z][A-Za-z0-9]{1,31});"\n    )\n    value = reference.sub(lambda match: html.unescape(match.group(0)), destination)\n    decoded: list[str] = []\n    cursor = 0\n    while cursor < len(value):\n        if (\n            value[cursor] == "\\\\"\n            and cursor + 1 < len(value)\n            and value[cursor + 1] in string.punctuation\n        ):\n            decoded.append(value[cursor + 1])\n            cursor += 2\n            continue\n        decoded.append(value[cursor])\n        cursor += 1\n    return "".join(decoded)\n\n\ndef _iter_inline_markdown_destinations(text: str):\n    """Yield rendered inline-link destinations while ignoring image destinations."""\n    cursor = 0\n    while cursor < len(text):\n        bracket = text.find("[", cursor)\n        if bracket < 0:\n            return\n        if _is_escaped_markdown_character(text, bracket):\n            cursor = bracket + 1\n            continue\n        label_end = _balanced_markdown_label_end(text, bracket)\n        if label_end is None or label_end + 1 >= len(text) or text[label_end + 1] != "(":\n            cursor = bracket + 1\n            continue\n        paren_start = label_end + 1\n        paren_end = _inline_link_closing_paren(text, paren_start)\n        if paren_end is None:\n            cursor = bracket + 1\n            continue\n        destination = _inline_link_destination(text[paren_start + 1:paren_end])\n        if destination is None:\n            cursor = bracket + 1\n            continue\n        image = (\n            bracket > 0\n            and text[bracket - 1] == "!"\n            and not _is_escaped_markdown_character(text, bracket - 1)\n        )\n        if not image:\n            yield destination\n        cursor = paren_end + 1\n\n\ndef _replace_inline_markdown_links_for_visibility', 1)

old = '    parser.feed("".join(characters))\n    parser.close()\n    return parser.violations\n'
assert old in text
new = '    live_markup = "".join(characters)\n\n    # Markdown links become anchors only after Markdown rendering, so the raw-HTML\n    # parser cannot enforce executable-scheme policy on them. Inspect the rendered\n    # Markdown structure before link labels are reduced to visible text. Raw HTML\n    # blocks/tags remain excluded so attribute text is not mistaken for Markdown.\n    markdown_characters = list(live_markup)\n    for start, end in html_spans:\n        markdown_characters[start:end] = " " * (end - start)\n    markdown_without_blocks = "".join(markdown_characters)\n    for match in reversed(list(PREFLIGHT_HTML_TAG.finditer(markdown_without_blocks))):\n        markdown_characters[match.start():match.end()] = " " * (match.end() - match.start())\n    markdown_source = "".join(markdown_characters)\n    if any(\n        _has_executable_url_scheme(_decode_markdown_destination_for_scheme(destination))\n        for destination in _iter_inline_markdown_destinations(markdown_source)\n    ):\n        # Reuse the existing executable-url policy kind so the registry\'s\n        # corpus-wide active-document gate consumes this shared finding too.\n        parser.violations.add("executable-url")\n\n    parser.feed(live_markup)\n    parser.close()\n    return parser.violations\n'
text = text.replace(old, new, 1)
policing.write_text(text)

Path("tests/test_pr4_executable_markdown_links.py").write_text('''"""Regression coverage for executable Markdown destinations on governed surfaces."""\n\nfrom pathlib import Path\nimport runpy\n\nimport pytest\n\n\nHERE = Path(__file__).parent\nPOLICING = runpy.run_path(str(HERE / "test_policing_context_roadmap.py"))\nREGISTRY = runpy.run_path(str(HERE / "test_research_reference_registry.py"))\n\n\n@pytest.mark.parametrize(\n    "destination",\n    (\n        "javascript:document.body.textContent=%27weakened%27",\n        "JAVASCRIPT:document.body.textContent=%27weakened%27",\n        "javascript&#58;document.body.textContent=%27weakened%27",\n        r"javascript\\:document.body.textContent=%27weakened%27",\n        "vbscript:msgbox%28%27weakened%27%29",\n    ),\n)\ndef test_shared_preflight_rejects_executable_inline_markdown_destinations(destination: str) -> None:\n    markdown = f"[source-gated research proposal]({destination})"\n    violations = POLICING["_governed_surface_html_violations"](markdown)\n    assert "executable-url" in violations\n\n\n@pytest.mark.parametrize(\n    "markdown",\n    (\n        "`[example](javascript:alert(1))`",\n        "<!-- [example](javascript:alert(1)) -->",\n        "```markdown\\n[example](javascript:alert(1))\\n```",\n        "![image](javascript:alert(1))",\n    ),\n)\ndef test_inert_or_non_anchor_markdown_does_not_trigger_executable_link_policy(markdown: str) -> None:\n    violations = POLICING["_governed_surface_html_violations"](markdown)\n    assert "executable-url" not in violations\n\n\ndef test_policing_validator_rejects_executable_markdown_link_on_required_clause() -> None:\n    roadmap = POLICING["ROADMAP"].read_text()\n    mutated = roadmap.replace(\n        "source-gated research proposal",\n        "[source-gated research proposal](javascript:document.body.textContent=%27weakened%27)",\n        1,\n    )\n    with pytest.raises(AssertionError, match="executable URL HTML"):\n        POLICING["_validate_policing_workstream"](mutated)\n\n\ndef test_registry_validator_rejects_executable_markdown_link_on_status_invariant() -> None:\n    corpus = REGISTRY["CORPUS"].read_text()\n    invariant = REGISTRY["REDISTRIBUTION_INVARIANT"]\n    mutated = corpus.replace(\n        invariant,\n        f"[{invariant}](javascript:document.body.textContent=%27weakened%27)",\n        1,\n    )\n    with pytest.raises(AssertionError):\n        REGISTRY["_validate_registry_corpus"](mutated)\n''')
